// Adapted from the guided project: https://youtu.be/g5JL2RIbThM
// Uses the workbook time range (default: last 24 hours), not a fixed historical interval.
// Count original events first, then choose one GeoIP match per source IP.
// The longest matching CIDR prefix is preferred; location remains approximate.
// Equally specific conflicting matches may select either location, but cannot multiply counts.
// Invalid/unmatched IPv4 addresses and missing/invalid coordinates are omitted from the map.
let GeoIPDB_FULL = _GetWatchlist("geoip")
| project network = tostring(network), latitude = todouble(latitude),
          longitude = todouble(longitude), cityname = tostring(cityname),
          countryname = tostring(countryname)
| extend PrefixLength = coalesce(toint(split(network, "/")[1]), 32);
SecurityEvent
| where Computer =~ "CORP-NET-EAST-1"
| where EventID == 4625
| where isnotempty(IpAddress) and IpAddress != "-"
| where isnotnull(parse_ipv4(IpAddress))
| summarize FailureCount = count() by IpAddress
| evaluate ipv4_lookup(GeoIPDB_FULL, IpAddress, network)
| summarize arg_max(PrefixLength, *) by IpAddress
| where latitude between (-90.0 .. 90.0) and longitude between (-180.0 .. 180.0)
| project FailureCount, AttackerIp = IpAddress, latitude, longitude,
          city = cityname, country = countryname,
          friendly_location = strcat(cityname, " (", countryname, ")")
